using JBooth.MicroVerseCore;
using Spirit604.CityEditor.Road;
using Spirit604.CityEditor.Utils;
using Spirit604.DotsCity.ThirdParty.RoadGeneration;
using Spirit604.Extensions;
using Spirit604.Gameplay.Road;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.Splines;

namespace Spirit604.DotsCity.ThirdParty.MVR
{
    public class MVR_Generator : MonoBehaviour
    {
        public enum DeadEndType { Default, DestroyVehicle, UTurn }

        [SerializeField] private MVR_Config mvr_Config;
        [SerializeField] private RSGeneratorConfig config;

        [SerializeField][Range(1f, 10f)] private float laneWidth = 3.75f;

        [Tooltip("" +
            "<b>Default</b> : no action performed\r\n\r\n" +
            "<b>DestroyVehicle</b> : node where traffic is destroyed on reach\r\n\r\n" +
            "<b>UTurn</b> : U-turns are created for dead ends")]
        [SerializeField] private DeadEndType deadEndType = DeadEndType.DestroyVehicle;
        [SerializeField] private bool autoBakeRoads = true;

        [SerializeField]
        private List<string> ignoreRoadNames = new() { "Tube", "Rollercoaster", "Railroad" };

        [Tooltip("Intersections that don't have a prefab. Create a new prefab with the same name as the Microverse Road and add it to the <b>MVR_Config</b>. Alternatively, create a new road segment, add a <b>MVR_UserSceneSegment</b> component, and sync it with this intersection.")]
        [SerializeField] private List<GameObject> notFound = new();

        [Tooltip("Road dead ends")]
        [SerializeField] private List<TrafficNode> deadEnds = new();

        [Tooltip("Intersections that can't be created automatically. In most cases, some of the road connectors are not connected")]
        [SerializeField] private List<Intersection> brokenIntersections = new();

        [Tooltip("The segment has the <b>MVR_UserSceneSegment</b> component, but the closest intersection could not be found")]
        [SerializeField] private List<RoadSegmentCreator> bindingNotFound = new();
        [SerializeField] private List<GameObject> ignoreRoads = new();

        private RoadParent roadParent;

        public MVR_Config Mvr_Config { get => mvr_Config; set => mvr_Config = value; }
        public RSGeneratorConfig Config { get => config; set => config = value; }

        private Dictionary<Intersection, RoadSegmentCreator> interersectionBinding = new();
        private Dictionary<Road, RoadSegmentCreator> roadBinding = new();
        private HashSet<Intersection> generateIntersections = new();

        public void Generate()
        {
            if (roadParent == null)
                roadParent = ObjectUtils.FindObjectOfType<RoadParent>();

            if (!roadParent)
            {
                Debug.Log("RoadParent not found.");
                return;
            }

            if (!mvr_Config)
            {
                Debug.Log("MVR config not assigned.");
                return;
            }

            if (!config)
            {
                Debug.Log("RSGeneratorConfig not assigned.");
                return;
            }

            Clear();

            var intersections = ObjectUtils.FindObjectsOfType<Intersection>();

            foreach (var intersection in intersections)
            {
                if (Ignore(intersection.gameObject)) continue;

                if (interersectionBinding.ContainsKey(intersection)) continue;

                var key = GetName(intersection.name);

                if (!mvr_Config.Prefabs.ContainsKey(key))
                {
                    if (!mvr_Config.AutoGeneratedIntersections.Contains(key))
                    {
                        notFound.Add(intersection.gameObject);
                    }
                    else
                    {
                        if (!generateIntersections.Contains(intersection))
                            generateIntersections.Add(intersection);
                    }

                    continue;
                }

                var prefab = mvr_Config.Prefabs[key];
                RoadSegmentCreator creator = CreateIntersection(intersection, prefab);

                interersectionBinding.Add(intersection, creator);

                config.ApplySettings(creator, RSGenType.Crossing, creator.name);
            }

            var roads = ObjectUtils.FindObjectsOfType<Road>();

            foreach (var road in roads)
            {
                if (Ignore(road.gameObject)) continue;

                var straight = new RoadSceneUtils.StraightSegmentSettings();

                var laneCount = GetLaneCount(road);

                if (laneCount != 3)
                {
                    if (laneCount == 1)
                    {
                        straight.IsOneWay = true;
                        straight.LaneCount = laneCount;
                    }
                    else
                    {
                        straight.LaneCount = laneCount / 2;
                    }
                }
                else
                {
                    straight.CustomLaneCount = new Vector2Int(2, 1);
                }

                TrafficNode startNode = GetConnectedIntersectionNode(road, false);
                TrafficNode endNode = GetConnectedIntersectionNode(road, true);

                if (startNode != null)
                {
                    if (startNode.IsOneWay)
                    {
                        straight.IsOneWay = true;
                        straight.IsEndOfOneWay = !startNode.IsEndOfOneWay;
                    }

                    straight.LaneCount = startNode.ExternalLaneCount;

                    if (startNode.LaneCountType == LaneCountType.Custom)
                        straight.CustomLaneCount = new Vector2Int(startNode.ExternalLaneCount, startNode.LaneCount);
                }

                if (startNode == null && endNode != null)
                {
                    if (endNode.IsOneWay)
                    {
                        straight.IsOneWay = true;
                        straight.IsEndOfOneWay = endNode.IsEndOfOneWay;
                    }

                    if (endNode.LaneCountType == LaneCountType.Custom)
                        straight.CustomLaneCount = new Vector2Int(endNode.LaneCount, endNode.ExternalLaneCount);
                }

                straight.LaneWidth = laneWidth;

                var creator = RoadSceneUtils.CreateStraightSegment(road.splineContainer, straight, segmentName: $"{road.name}_segment");

                roadBinding.Add(road, creator);
                creator.transform.SetParent(roadParent.transform);

                var startNode2 = creator.TryToGetNode(0);

                if (startNode != null)
                {
                    startNode.SetMerge(startNode2);
                }
                else
                {
                    if (!Generated(road.beginConnector))
                        AddDeadEnd(startNode2);
                }

                var endNode2 = creator.TryToGetNode(1);

                if (endNode != null)
                {
                    endNode.SetMerge(endNode2);
                }
                else
                {
                    if (!Generated(road.endConnector))
                        AddDeadEnd(endNode2);
                }

                config.ApplySettings(creator, RSGenType.SplineRoad, creator.name);
                config.ApplyPostCreationSplineSettings(creator);
            }

            var connectedRoads = new List<RoadSegmentCreator>();

            foreach (var intersection in generateIntersections)
            {
                connectedRoads.Clear();

                foreach (var connectionPoint in intersection.connectionPoints)
                {
                    if (connectionPoint.road == null)
                        continue;

                    var connectedRoad = roadBinding[connectionPoint.road];

                    connectedRoads.Add(connectedRoad);
                }

                if (intersection.connectionPoints.Count() != connectedRoads.Count)
                {
                    brokenIntersections.Add(intersection);
                    continue;
                }

                var newIntersection = RoadSceneUtils.CreateIntersection(connectedRoads, segmentName: intersection.name);

                newIntersection.transform.SetParent(roadParent.transform, true);
            }

            if (autoBakeRoads)
                roadParent.BakePathData();
        }

        private RoadSegmentCreator CreateIntersection(Intersection intersection, RoadSegmentCreator prefab)
        {
#if UNITY_EDITOR

            var prefabInstance = UnityEditor.PrefabUtility.InstantiatePrefab(prefab.gameObject) as GameObject;
            UnityEditor.PrefabUtility.UnpackPrefabInstance(prefabInstance, UnityEditor.PrefabUnpackMode.OutermostRoot, UnityEditor.InteractionMode.AutomatedAction);

            prefabInstance.transform.SetParent(roadParent.transform);
            prefabInstance.transform.SetPositionAndRotation(intersection.transform.position, intersection.transform.rotation);

            return prefabInstance.GetComponent<RoadSegmentCreator>();
#else
            return Instantiate(prefab, intersection.transform.position, intersection.transform.rotation, roadParent.transform);
#endif
        }

        private void AddDeadEnd(TrafficNode deadEndNode)
        {
            deadEnds.Add(deadEndNode);

            switch (deadEndType)
            {
                case DeadEndType.DestroyVehicle:
                    {
                        deadEndNode.TrafficNodeType = TrafficNodeType.DestroyVehicle;
                        EditorSaver.SetObjectDirty(deadEndNode);
                        break;
                    }
                case DeadEndType.UTurn:
                    {
                        RoadSceneUtils.CreateUTurnPaths(deadEndNode);
                        break;
                    }
            }
        }

        private TrafficNode GetConnectedIntersectionNode(Road road, bool last)
        {
            if (!last)
            {
                if (road.beginConnector != null && road.beginConnector.owner != null && interersectionBinding.ContainsKey(road.beginConnector.owner))
                {
                    var intersection = interersectionBinding[road.beginConnector.owner];

                    var knot = GetKnotPosition(road.splineContainer, road.splineContainer.Spline.Knots.ElementAt(0).Position);
                    var closestNode = intersection.TryToGetClosestNode(knot);
                    return closestNode;
                }
            }
            else
            {
                if (road.endConnector != null && road.endConnector.owner != null && interersectionBinding.ContainsKey(road.endConnector.owner))
                {
                    var intersection = interersectionBinding[road.endConnector.owner];

                    var knot = GetKnotPosition(road.splineContainer, road.splineContainer.Spline.Knots.Last().Position);
                    var closestNode = intersection.TryToGetClosestNode(knot);
                    return closestNode;
                }
            }

            return null;
        }

        private bool Generated(Intersection.ConnectionPoint connection)
        {
            return connection != null && connection.owner != null && generateIntersections.Contains(connection.owner);
        }

        private static Vector3 GetKnotPosition(SplineContainer splineContainer, Vector3 point)
        {
            return splineContainer.transform.TransformPoint(point);
        }

        private int GetLaneCount(Road road)
        {
            var name = road.config.name;

            if (name.Contains("1 Lane"))
                return 1;

            if (name.Contains("2 Lane"))
                return 2;

            if (name.Contains("3 Lane"))
                return 3;

            if (name.Contains("4 Lane"))
                return 4;

            return 0;
        }

        private bool Ignore(GameObject road)
        {
            for (int i = 0; i < ignoreRoadNames.Count; i++)
            {
                if (road.name.Contains(ignoreRoadNames[i]))
                {
                    ignoreRoads.Add(road.gameObject);
                    return true;
                }
            }

            return false;
        }

        public static string GetName(string sourceName)
        {
            var index1 = sourceName.IndexOf('(');
            var index2 = sourceName.IndexOf(')');

            if (index1 >= 0 && index2 >= 0)
            {
                return sourceName.Substring(0, index1 - 1);
            }

            return sourceName;
        }

        private void Clear()
        {
            interersectionBinding.Clear();
            bindingNotFound.Clear();

            var creators = roadParent.GetComponentsInChildren<RoadSegmentCreator>().ToList();

            int index = 0;

            while (creators.Count > index)
            {
                var creator = creators[index];

                var sceneSegment = creator.GetComponent<MVR_UserSceneSegment>();

                if (sceneSegment == null)
                {
                    creators.RemoveAt(index);
                    DestroyImmediate(creator.gameObject);
                }
                else
                {
                    var relatedIntersection = sceneSegment.RelatedIntersection;

                    if (relatedIntersection != null)
                    {
                        interersectionBinding.Add(relatedIntersection, creator);
                    }
                    else
                    {
                        bindingNotFound.Add(creator);
                        Debug.LogError($"MVR_Generator. MVR_UserSceneSegment {sceneSegment.name} relatedIntersection not found");
                    }

                    index++;
                }
            }

            roadBinding.Clear();
            notFound.Clear();
            deadEnds.Clear();
            generateIntersections.Clear();
            brokenIntersections.Clear();
            ignoreRoads.Clear();
        }
    }
}